import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Vector3,
  Quaternion,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  uv,
  mul,
  add,
  vec2,
  vec4,
} from 'three/tsl';
import { killTweensOf } from 'gsap';

export default function createNode(config, ctx) {
  // --- Prepare texture ------------------------------------------------------
  const tex = ctx.textureLoader(config.assets?.imageUrl ?? '');

  // --- Atlas region handling -----------------------------------------------
  // Expect config.atlasRegion = { x, y, width, height, atlasWidth, atlasHeight }
  const region = config.atlasRegion || {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
    atlasWidth: 512,
    atlasHeight: 320,
  };

  const uvOffset = vec2(
    region.x / region.atlasWidth,
    region.y / region.atlasHeight
  );
  const uvScale = vec2(
    region.width / region.atlasWidth,
    region.height / region.atlasHeight
  );

  const uvNode = add(mul(uv(), uvScale), uvOffset);
  const texNode = texture(tex, uvNode);

  // --- Material ------------------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.mapNode = texNode;
  material.transparent = true;
  material.depthTest = true;
  material.depthWrite = false;

  // --- Geometry ------------------------------------------------------------
  const aspect = region.width / region.height;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // --- Mesh -----------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.name = config.id || 'journal-card-2';

  // Position / rotation / scale from config
  const pos = config.position || { x: 0, y: -0.3, z: 0 };
  mesh.position.set(pos.x, pos.y, pos.z);

  const rot = config.rotation || { x: 0, y: 0, z: 0 };
  mesh.rotation.set(rot.x, rot.y, rot.z);

  const scl = config.scale || { x: 1, y: 1, z: 1 };
  mesh.scale.set(scl.x, scl.y, scl.z);

  // --- Billboard logic ------------------------------------------------------
  mesh.onBeforeRender = function (_renderer, _scene, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  // --- Handlers placeholder -------------------------------------------------
  mesh.userData.handlers = {};

  // --- Cleanup --------------------------------------------------------------
  mesh.userData.cleanup = function () {
    killTweensOf(mesh);
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
  };

  return mesh;
}
